 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txa_maindocContn_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.setLength(selfVar.value, 'divRemk','10000');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52610.txa_maindocContn_onkeyup' }); }
};

/**
