///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    if (loadTp !== '0' && loadTp !== '4') {
        scwin.setDataVars(loadTp);
    }
    const uploadCode = (String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))));
    const isOk = (String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))));
    if (isOk !== '') {
        if (uploadCode === '0') {
            if (isOk === 'true') {
                await $c.win.alert('저장되었습니다.');
            } else {
                await $c.win.alert('저장중 오류가 발생하였습니다.');
            }
        } else {
            if (uploadCode === '1') {
                await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
            } else {
                if (uploadCode === '2') {
                    await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
                } else {
                    await $c.win.alert('저장시 오류가 발생하였습니다.');
                }
            }
        }
    }
};

/**
 * @method
 * @name setDataVars
 * @description set Data Vars 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.setDataVars = function (ver) {
    if (ver === '2' || ver === '3') {
        scwin.setFileDisable();
    }
};

/**
 * @method
 * @name setFileDisable
 * @description set File Disable 처리
 * @returns {void}
 * @hidden N
 */
scwin.setFileDisable = function () {
    const obj1 = $c.util.getComponent('upd_attachFile');
    obj1.setDisabled(true);
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {*} bz_procs_no bz_procs_no
 * @param {*} com_abbrv com_abbrv
 * @param {*} isur_cd isur_cd
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (bz_procs_no, com_abbrv, isur_cd) {
    $c.util.getComponent('dma_doSaveReq').set('chgGrndListBzProcsNo', bz_procs_no);
    $c.util.getComponent("ipt_comAbbrv").setValue(com_abbrv);
    $c.util.getComponent("ipt_isurCd").setValue(isur_cd);
};

/**
 * @method
 * @name doSave
 * @description do Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
